    "pt": { "t": "Medo antes de uma EVA ou de uma tarefa crítica", "q": "medo eva caminhada espacial saida ao exterior nervoso nervosismo tarefa critica assustado antes da saida pavor receio", "a": "Ficar nervoso antes de um trabalho de alto risco é normal e pode aguçar o foco.", "s": ["Ensaie o procedimento com seu parceiro.", "Use respiração lenta antes de começar.", "Combinem palavras claras de parada e pontos de contato."], "e": "Se o medo impedir você de trabalhar com segurança, avise o comandante — adiar é uma opção." },
    "fr": { "t": "Peur avant une sortie extravéhiculaire ou une tâche critique", "q": "peur sortie extravehiculaire sortie dans l espace eva nerveux stress tache critique effraye avant la sortie angoisse trac", "a": "Être nerveux avant un travail à haut risque est normal et peut aiguiser la concentration.", "s": ["Répétez la procédure avec votre partenaire.", "Utilisez une respiration lente avant de commencer.", "Convenez de mots d’arrêt clairs et de points de contact."], "e": "Si la peur vous empêche de travailler en sécurité, prévenez le commandant — reporter est une option." }
